// T-AC-06: mobile views fit the viewport and keyboard users can reach main content.
test("T33 keeps the mobile views within the viewport and supports the keyboard skip link", async ({
  page,
}) => {
  await page.setViewportSize({ width: 390, height: 844 });
  for (const route of ["/", "/projects/new", "/pipelines", "/infrastructure", "/agents"]) {
    await page.goto(route);
    await expect(page.locator("h1")).toBeVisible();
    const horizontalOverflow = await page.evaluate(
      () => document.documentElement.scrollWidth - window.innerWidth,
    );
    expect(horizontalOverflow, `Horizontal overflow at ${route}`).toBeLessThanOrEqual(1);
  }

  await page.goto("/");
  await expect(page.getByRole("heading", { name: "Vue d’ensemble", exact: true })).toBeVisible();
  await page.screenshot({ path: "artifacts/console-mobile.png", fullPage: true });
  await page.keyboard.press("Tab");
  await expect(page.getByRole("link", { name: "Aller au contenu", exact: true })).toBeFocused();
  await page.keyboard.press("Enter");
  await expect(page.getByRole("main")).toBeFocused();
});
